tokens:
--scheme: light;
color-scheme: light;
--bg: #f4efe3;
--bg2: #ece5d4;
--surface: #fffdf7;
--surface2: #ebe3cf;
--ink: #1f2a22;
--muted: #3d4a40;
--faint: #55625a;
--cardmeta: #2c3830;
--gold: #b0401c;
--gold-soft: #8f3415;
--gold-deep: #1f2a22;
--on-gold: #ffffff;
--ink-soft: #3d4a40;
--line: rgba(31, 42, 34, 0.16);
--line-strong: #b0401c;
--ok: #1f6b33;
--warn: #7f5800;
--bad: #b0220f;
--shadow: 0 1px 1px rgba(70, 55, 30, 0.14), 0 6px 0 -2px rgba(70, 55, 30, 0.10), 0 10px 18px rgba(70, 55, 30, 0.10);
--elev-1: 0 1px 1px rgba(70, 55, 30, 0.14), 0 3px 6px rgba(70, 55, 30, 0.10);
--elev-2: 0 2px 2px rgba(70, 55, 30, 0.14), 0 10px 22px rgba(70, 55, 30, 0.14);
--elev-3: 0 4px 6px rgba(70, 55, 30, 0.16), 0 24px 60px rgba(70, 55, 30, 0.22);
--scrim: rgba(31, 42, 34, 0.42);
--focus: #2f6fd6;
--th-bg: #ebe3cf;
--tabgrad1: #ebe3cf; --tabgrad2: #fffdf7;
--toastgrad1: #ebe3cf; --toastgrad2: #fffdf7;
--foot-bg: rgba(244, 239, 227, 0.95);
--drawerbar-bg: rgba(255, 253, 247, 0.96);
--ph-bg: #ebe3cf;
--sel-bg: rgba(176, 64, 28, 0.15);
--row-hover: rgba(176, 64, 28, 0.07);
--hold-bg: linear-gradient(135deg, #ebe3cf, #fffdf7);
--skeleton1: #ebe3cf; --skeleton2: #f4efe3;
--grain-op: 0.035;
--wing-dur: 0.42s;
--wing-rise: 14px;
/* legacy aliases resolved on <html> */
--text: var(--ink); --panel: var(--surface); --chip: var(--surface2); --missing: var(--faint);
--border: var(--line); --gold-dim: var(--gold-deep); --danger: var(--bad);
--serif: "Avenir Next", "Futura", "Century Gothic", "Segoe UI", system-ui, -apple-system, sans-serif;
--radius: 10px;
/* the card stock behind each card (styles/style-layer.css, ui "papercut"): two layers, hill green then ochre */
--cut-l1: #a9c9a4;
--cut-l2: #dcae5c;
--cut-shadow: rgba(70, 55, 30, 0.22);
/* the dark display-case interior used by the instrument panels (styles/style-layer.css, ui "paper"): deep forest card */
--case-bg: #1d2b24;
--case-bg2: #22342b;
--case-surface: #283d32;
--case-surface2: #33503f;
--case-ink: #ffffff;
--case-muted: #dbe8d8;
--case-faint: #b8cdb6;
--case-gold: #f3b98f;
--case-gold-soft: #ffd7b8;
--case-on-gold: #1d2b24;
/* the page palette again, for paper labels inside a case */
--paper-bg: #f4efe3;
--paper-bg2: #ece5d4;
--paper-surface: #fffdf7;
--paper-surface2: #ebe3cf;
--paper-ink: #1f2a22;
--paper-muted: #3d4a40;
--paper-faint: #55625a;
--paper-gold: #b0401c;
--paper-gold-soft: #8f3415;
--paper-on-gold: #ffffff;

